import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"十一真","description":"","frontmatter":{"title":"十一真","date":"2026-11-17T00:00:00.000Z","seq":11,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/十一真.md","filePath":"blogs/声律启蒙·上卷/十一真.md"}'),r={name:"blogs/声律启蒙·上卷/十一真.md"};function p(_,e,l,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="十一真" tabindex="-1">十一真 <a class="header-anchor" href="#十一真" aria-label="Permalink to &quot;十一真&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">邪对正，假对真，獬豸对麒麟。韩卢对苏雁，陆橘对庄椿。韩五鬼，李三人，北魏对西秦。蝉鸣哀暮夏，莺啭怨残春。野烧焰腾红烁烁，溪流波皱碧粼粼。行无踪，居无庐，颂成酒德；动有时，藏有节，论著钱神。</p><p class="poem-stanza">哀对乐，富对贫，好友对嘉宾。弹冠对结绶，白日对青春。金翡翠，玉麒麟，虎爪对龙麟。柳塘生细浪，花径起香尘。闲爱登山穿谢屐，醉思漉酒脱陶巾。雪冷霜严，倚槛松筠同傲岁；日迟风暖，满园花柳各争春。</p><p class="poem-stanza">香对火，炭对薪，日观对天津。禅心对道眼，野妇对宫嫔。仁无敌，德有邻，万石对千钧。滔滔三峡水，冉冉一溪冰。充国功名当画阁，子张言行贵书绅。笃志诗书，思入圣贤绝域；忘情官爵，羞沾名利纤尘。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
